From Coq Require Import ZArith List.
From Qs8Mul Require Export IntrinsicModel.
Import ListNotations. Local Open Scope Z_scope.
(* The32 fields are all retained, including arbitrary inactive values. The
   total function defaults outside0..31 are representation defaults only;
   every semantic use is guarded by0<=i<VL<=32. *)
Definition qm_list32 (x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31:Z):list Z:=[x0;x1;x2;x3;x4;x5;x6;x7;x8;x9;x10;x11;x12;x13;x14;x15;x16;x17;x18;x19;x20;x21;x22;x23;x24;x25;x26;x27;x28;x29;x30;x31].
Definition qm_vec32 (x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 i:Z):Z:=nth(Z.to_nat i)(qm_list32 x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)0.
Definition qm_fpvec32 (x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31:fp32)(i:Z):fp32:=nth(Z.to_nat i)[x0;x1;x2;x3;x4;x5;x6;x7;x8;x9;x10;x11;x12;x13;x14;x15;x16;x17;x18;x19;x20;x21;x22;x23;x24;x25;x26;x27;x28;x29;x30;x31](fp32_of_bits 0).
Definition qm_take32(n:Z)(L:list Z):list Z:=firstn(Z.to_nat n)L.
